function renderNode(node,container){for(const [name,child] of [...node.dirs].sort()){const details=document.createElement('details'),collapsed=treeCollapsedDirectories.has(child.path);details.open=!collapsed;const summary=document.createElement('summary'),label=document.createElement('span'),icon=lucideIcon(collapsed?'folder':'folder-open');summary.tabIndex=0;summary.className='directory';label.className='file-name';label.textContent=name;summary.append(icon,label);details.ontoggle=()=>{if(details.open)treeCollapsedDirectories.delete(child.path);else treeCollapsedDirectories.add(child.path);window.workspaceIcons.render(icon,details.open?'folder-open':'folder')};summary.oncontextmenu=event=>openTreeMenu(event,child.path,summary,'directory',child.path);summary.onkeydown=event=>{if(event.key==='Enter'||event.key===' '){event.preventDefault();details.open=!details.open}else if(event.key==='ContextMenu'||(event.shiftKey&&event.key==='F10'))openTreeMenu(event,child.path,summary,'directory',child.path)};bindUploadDrop(summary,child.path);details.append(summary);renderNode(child,details);container.append(details)}for(const file of node.files.sort((a,b)=>a.name.localeCompare(b.name))){const button=document.createElement('button'),label=document.createElement('span'),parent=file.path.includes('/')?file.path.slice(0,file.path.lastIndexOf('/')):'',presentation=treeFilePresentation(file.path);button.className='file '+presentation.kind+(file.path===currentPath?' active':'');label.className='file-name';label.textContent=file.name;button.append(lucideIcon(presentation.icon),label);if(presentation.entryLabel){const badge=document.createElement('span');badge.className='entry-badge';badge.textContent=presentation.entryLabel;button.append(badge);button.title=presentation.entryLabel;button.setAttribute('aria-label',presentation.entryLabel+' · '+file.name)}button.onclick=()=>loadFile(file.path);button.oncontextmenu=event=>openTreeMenu(event,parent,button,'file',file.path);button.onkeydown=event=>{if(event.key==='ContextMenu'||(event.shiftKey&&event.key==='F10'))openTreeMenu(event,parent,button,'file',file.path)};bindUploadDrop(button,parent);container.append(button)}}
function renderTree(data){treeFiles=new Set(data.files);treeDirectories=new Set(data.directories||[]);treeCollapsedDirectories=new Set([...treeCollapsedDirectories].filter(path=>treeDirectories.has(path)));tree.replaceChildren();renderNode(nodeTree(data.files,data.directories||[]),tree);q('treeEmpty').hidden=treeFiles.size+treeDirectories.size>0;bindUploadDrop(tree,'')}
async function loadTree(){const [data]=await Promise.all([api(endpoint('files','')).then(r=>r.json()),refreshProjectEntryPaths()]);renderTree(data);if(!currentPath||!data.files.includes(currentPath)){const first=data.files.find(p=>/\.(json|html|css|js|mjs|md|txt)$/.test(p));if(first)await loadFile(first)}}
function showEditor(){currentKind='text';q('imageViewer').style.display='none';editor.getWrapperElement().style.display='block';q('copyCurrentFile').disabled=!currentPath;if(!currentPath)q('lock').hidden=true;if(imageUrl){URL.revokeObjectURL(imageUrl);imageUrl=null}setTimeout(()=>editor.refresh(),0)}
function isImage(path){return /\.(png|jpe?g|gif|webp|svg)$/i.test(path)}
