function joinedPath(directory,name){return directory?directory+'/'+name:name}
function requestedEntryName(label,initial=''){const value=prompt(label,initial);if(value===null)return null;const name=value.trim();if(!name||name==='.'||name==='..'||/[\\/<>:"|?*\u0000-\u001f]/.test(name))throw new Error(tr('workspace.invalid_entry_name'));return name}
