async function uploadTreeFiles(files,destination=treeMenuPath){let uploaded=0;for(const file of files){const name=file.name.trim();if(!name||/[\\/<>:"|?*\u0000-\u001f]/.test(name))throw new Error(tr('workspace.invalid_upload_filename',{name:file.name}));if(file.size>2*1024*1024)throw new Error(tr('workspace.upload_too_large',{name:file.name}));const path=joinedPath(destination,name);if(treeDirectories.has(path))throw new Error(tr('workspace.upload_conflicts_directory',{path}));let baseRevision=0;if(treeFiles.has(path)){if(!confirm(tr('workspace.confirm_overwrite',{path})))continue;const current=await api(endpoint('asset',path));baseRevision=Number(current.headers.get('X-Playmesh-Revision')||0)}const content=bufferToBase64(await readUploadBuffer(file));await api(endpoint('file',path),{method:'PUT',body:JSON.stringify({content,encoding:'base64',baseRevision,clientId})});treeFiles.add(path);uploaded+=1;message.textContent=tr('workspace.uploading_file',{uploaded:formatInteger(uploaded),total:formatInteger(files.length),name})}await loadTreeOnly();message.textContent=tr('workspace.files_uploaded',{count:formatInteger(uploaded),destination:destination||tr('workspace.project_root')})}
function rememberTreeEntry(operation){if(!treeMenuItemPath||treeMenuKind==='root')return;treeClipboard={operation,source:treeMenuItemPath,kind:treeMenuKind};message.textContent=tr(operation==='copy'?'workspace.file_copied_for_paste':'workspace.file_cut_for_paste',{path:treeMenuItemPath});if(operation==='copy')showWorkspaceMessage(tr('workspace.copy_succeeded'))}
