function normalizeExtractDestination(value){let path=String(value??'').trim().replaceAll('\\','/');if(path===''||path==='.'||path==='/')return'';if(path.startsWith('./'))path=path.slice(2);if(path.startsWith('/')||/^[a-z]:/i.test(path))throw new Error(tr('workspace.invalid_extract_destination'));path=path.replace(/\/+$/,'');const segments=path.split('/');if(!segments.length||['.playmesh','cache','data'].includes(segments[0])||segments.some(segment=>!segment||segment==='.'||segment==='..'||/[<>:"|?*\u0000-\u001f]/.test(segment)))throw new Error(tr('workspace.invalid_extract_destination'));return segments.join('/')}
