async function deleteTreeEntry(){const path=treeMenuItemPath,kind=treeMenuKind;if(!path||kind==='root')return;const label=tr(kind==='directory'?'workspace.directory_with_contents':'workspace.file');if(!confirm(tr('workspace.confirm_delete_entry',{label,path})))return;if(kind==='directory'){await api(endpoint('directory',path),{method:'DELETE',body:JSON.stringify({clientId})})}else{const current=await api(endpoint('asset',path)),baseRevision=Number(current.headers.get('X-Playmesh-Revision')||0);await api(endpoint('file',path),{method:'DELETE',body:JSON.stringify({baseRevision,clientId})})}if(currentPath===path||(kind==='directory'&&currentPath.startsWith(path+'/'))){currentPath='';editor.setValue('');showEditor()}await loadTree();message.textContent=tr('workspace.entry_deleted',{path})}
function historyScopeLabel(){return historyPath||tr('workspace.entire_workspace')}
function historyButton(title,detail,onClick){const button=document.createElement('button'),strong=document.createElement('strong'),small=document.createElement('small');strong.textContent=title;small.textContent=detail;button.append(strong,small);button.onclick=()=>onClick(button);return button}
function renderHistoryOperationItems(){historyOperations.replaceChildren();if(!historyOperationItems.length){historyOperations.textContent=tr('workspace.no_local_history');return}let selectedButton=null;for(const operation of historyOperationItems){const time=formatDateTime(operation.updatedAt),detail=tr('workspace.history_change_count',{time,count:formatInteger(operation.changeCount)}),button=historyButton(localizedHistorySummary(operation),detail,item=>selectHistoryOperation(operation,item));if(operation.id===historyOperationId)selectedButton=button;historyOperations.append(button)}if(selectedButton)selectedButton.classList.add('active');else historyOperations.firstElementChild?.click()}
async function openLocalHistory(path){historyPath=path;historyOperationId='';historyChangesData=[];historySelectedChange=null;historyMergeState=null;const scope=path||tr('workspace.entire_workspace');q('historyTitle').textContent=tr('workspace.local_history_scope',{scope});historyOperations.textContent=tr('workspace.loading');historyChanges.textContent='';showMergePlaceholder(q('historyMergeHost'),tr('workspace.select_history_file'));q('historyChangeMeta').textContent=tr('workspace.select_history_operation');q('restoreBefore').disabled=true;q('restoreAfter').disabled=true;q('historyApplyChunks').disabled=true;q('historyModal').style.display='grid';const data=await api(endpoint('local-history',path)).then(r=>r.json());historyOperationItems=Array.isArray(data.operations)?data.operations:[];renderHistoryOperationItems()}
async function selectHistoryOperation(operation,button){historyOperationId=operation.id;historySelectedChange=null;historyMergeState=null;historyOperations.querySelectorAll('button').forEach(item=>item.classList.toggle('active',item===button));q('restoreBefore').disabled=false;q('restoreAfter').disabled=false;q('historyApplyChunks').disabled=true;historyChanges.textContent=tr('workspace.loading_diff');showMergePlaceholder(q('historyMergeHost'),tr('workspace.reading_history_diff'));const base=endpoint('local-history/diff',historyPath),url=base+(historyPath?'&':'?')+'operationId='+encodeURIComponent(operation.id),data=await api(url).then(r=>r.json());historyChangesData=data.changes;historyChanges.replaceChildren();if(!data.changes.length){historyChanges.textContent=tr('workspace.no_diff_in_scope');q('historyChangeMeta').textContent=tr('workspace.no_difference');showMergePlaceholder(q('historyMergeHost'),tr('workspace.no_text_diff_in_operation'));return}for(const change of data.changes){const sign=change.change==='added'?'+':change.change==='deleted'?'-':'±',detail=change.kind==='directory'?tr('workspace.directory'):tr('workspace.changed_line_counts',{sign,added:formatInteger(change.addedLines),removed:formatInteger(change.removedLines)});historyChanges.append(historyButton(change.path,detail,button=>showHistoryChange(change,button).catch(error=>message.textContent=error.message)))}historyChanges.firstElementChild?.click()}
