function textFilePaths(){return [...treeFiles].filter(path=>/\.(json|html?|css|js|mjs|md|txt|svg|xml|ya?ml)$/i.test(path)).sort((a,b)=>a.localeCompare(b))}
function diffOption(value,label=value){const option=document.createElement('option');option.value=value;option.textContent=label;return option}
function splitDiffLines(value){const lines=String(value??'').replace(/\r\n?/g,'\n').split('\n');if(lines.length>1&&lines.at(-1)==='')lines.pop();return lines}
function indexedDiff(left,right){const a=splitDiffLines(left),b=splitDiffLines(right),operations=[],size=Math.max(a.length,b.length);for(let index=0;index<size;index++){if(a[index]===b[index]&&index<a.length&&index<b.length)operations.push({type:'same',left:index+1,right:index+1,text:a[index]});else{if(index<a.length)operations.push({type:'remove',left:index+1,right:null,text:a[index]});if(index<b.length)operations.push({type:'add',left:null,right:index+1,text:b[index]})}}return operations}
