function showMergePlaceholder(host,text){host.replaceChildren();const placeholder=document.createElement('div');placeholder.className='merge-placeholder';placeholder.textContent=host.id==='quickMergeHost'?tr('workspace.conversation_console_help'):text;host.append(placeholder)}
