async function readWorkspaceText(path){try{const response=await api(endpoint('file',path));return{exists:true,text:await response.text(),revision:Number(response.headers.get('X-Playmesh-Revision')||0)}}catch(error){if(error.status===404)return{exists:false,text:'',revision:0};throw error}}
