function diffSummary(leftText,rightText){const operations=lineDiff(leftText,rightText),added=operations.filter(item=>item.type==='add').length,removed=operations.filter(item=>item.type==='remove').length;return added||removed?tr('workspace.diff_line_summary',{added:formatInteger(added),removed:formatInteger(removed)}):tr('workspace.content_identical')}
