  const panelId=hostId+'Dropdown';
  host.replaceChildren();
  host.className='capability-picker';
  field.className='capability-picker-field';
  chips.className='capability-picker-chips';
  search.type='search';
  search.className='capability-picker-search';
  search.placeholder=tr('workspace.capability_search_placeholder');
  search.setAttribute('aria-label',search.placeholder);
  search.setAttribute('role','combobox');
  search.setAttribute('aria-autocomplete','list');
