function capabilitySchemaDefault(schema){if(schema&&Object.prototype.hasOwnProperty.call(schema,'default'))return schema.default;if(Array.isArray(schema?.enum)&&schema.enum.length)return schema.enum[0];const type=schema?.type||(schema?.properties?'object':'object');if(type==='object'){const value={};for(const [name,property] of Object.entries(schema?.properties||{})){if((schema.required||[]).includes(name)||Object.prototype.hasOwnProperty.call(property,'default'))value[name]=capabilitySchemaDefault(property)}return value}if(type==='array')return[];if(type==='boolean')return false;if(type==='integer'||type==='number')return Number(schema?.minimum||0);if(type==='null')return null;return''}
function capabilityClone(value){return value===undefined?undefined:JSON.parse(JSON.stringify(value))}
function capabilityDraftValue(key,schema){if(!capabilityTestDrafts.has(key))capabilityTestDrafts.set(key,capabilitySchemaDefault(schema));return capabilityClone(capabilityTestDrafts.get(key))}
function capabilityPrimitiveControl(schema,value,onChange){let input;const values=Array.isArray(schema?.enum)?schema.enum:null;if(values?.length){input=document.createElement('select');for(const item of values){const option=document.createElement('option');option.value=JSON.stringify(item);option.textContent=String(item);input.append(option)}input.value=JSON.stringify(value);input.onchange=()=>onChange(JSON.parse(input.value));return input}const type=schema?.type;if(type==='boolean'){input=document.createElement('select');for(const item of [true,false]){const option=document.createElement('option');option.value=String(item);option.textContent=String(item);input.append(option)}input.value=String(value===true);input.onchange=()=>onChange(input.value==='true');return input}if(type==='integer'||type==='number'){input=document.createElement('input');input.type='number';if(Number.isFinite(Number(schema?.minimum)))input.min=String(schema.minimum);if(Number.isFinite(Number(schema?.maximum)))input.max=String(schema.maximum);if(Number.isFinite(Number(schema?.multipleOf)))input.step=String(schema.multipleOf);else if(type==='integer')input.step='1';input.value=String(value??0);input.required=true;input.oninput=()=>{const number=Number(input.value);if(Number.isFinite(number))onChange(type==='integer'?Math.trunc(number):number)};return input}if(type==='null'){input=document.createElement('span');input.className='capability-null-value';input.textContent='null';return input}input=document.createElement('input');input.type=schema?.format==='password'?'password':'text';input.value=String(value??'');if(Number.isFinite(Number(schema?.minLength)))input.minLength=Number(schema.minLength);if(Number.isFinite(Number(schema?.maxLength)))input.maxLength=Number(schema.maxLength);if(typeof schema?.pattern==='string')input.pattern=schema.pattern;input.oninput=()=>onChange(input.value);return input}
function capabilitySchemaNode(schema,value,onChange){const type=schema?.type||(schema?.properties?'object':schema?.items?'array':'string');if(type==='object'){const objectHost=document.createElement('div'),properties=schema?.properties||{},required=new Set(schema?.required||[]);objectHost.className='capability-schema-object';let objectValue=value&&typeof value==='object'&&!Array.isArray(value)?{...value}:{};const entries=Object.entries(properties);if(!entries.length){const empty=document.createElement('p');empty.className='capability-test-muted';empty.textContent=tr('workspace.no_parameters_defined');objectHost.append(empty);return objectHost}for(const [name,property] of entries){const row=document.createElement('section'),head=document.createElement('div'),title=document.createElement('span'),fieldName=document.createElement('strong'),badge=document.createElement('small'),toggleWrap=document.createElement('label'),toggle=document.createElement('input'),content=document.createElement('div'),help=document.createElement('small'),isRequired=required.has(name);let included=isRequired||Object.prototype.hasOwnProperty.call(objectValue,name),fieldValue=included?objectValue[name]:capabilitySchemaDefault(property);row.className='capability-schema-field';head.className='capability-schema-field-head';fieldName.textContent=name;badge.textContent=capabilityParameterRequirementText(isRequired);title.append(fieldName,badge);toggle.type='checkbox';toggle.checked=included;toggle.disabled=isRequired;toggle.setAttribute('aria-label',tr('workspace.include_parameter',{name}));toggleWrap.className='capability-parameter-toggle';toggleWrap.append(toggle,document.createTextNode(tr('workspace.include')));head.append(title,toggleWrap);content.className='capability-schema-field-control';const renderControl=()=>{content.replaceChildren();if(!included)return;content.append(capabilitySchemaNode(property,fieldValue,next=>{fieldValue=next;objectValue={...objectValue,[name]:next};onChange(objectValue)}))};toggle.onchange=()=>{included=toggle.checked;if(included)objectValue={...objectValue,[name]:fieldValue};else{objectValue={...objectValue};delete objectValue[name]}onChange(objectValue);renderControl()};row.append(head,content);if(property?.description){help.textContent=String(property.description);row.append(help)}objectHost.append(row);renderControl()}return objectHost}if(type==='array'){const arrayHost=document.createElement('div'),items=document.createElement('div'),add=document.createElement('button'),itemSchema=schema?.items||{type:'string'};let arrayValue=Array.isArray(value)?[...value]:[];arrayHost.className='capability-schema-array';items.className='capability-schema-array-items';add.type='button';add.textContent=tr('workspace.add_array_item');const renderItems=()=>{items.replaceChildren(...arrayValue.map((item,index)=>{const row=document.createElement('section'),head=document.createElement('div'),label=document.createElement('strong'),remove=document.createElement('button'),content=document.createElement('div');row.className='capability-schema-array-item';head.className='capability-schema-array-item-head';label.textContent=tr('workspace.array_item',{index:formatInteger(index+1)});remove.type='button';remove.textContent=tr('workspace.remove_array_item');remove.onclick=()=>{arrayValue.splice(index,1);onChange([...arrayValue]);renderItems()};head.append(label,remove);content.append(capabilitySchemaNode(itemSchema,item,next=>{arrayValue[index]=next;onChange([...arrayValue])}));row.append(head,content);return row}))};add.onclick=()=>{arrayValue.push(capabilitySchemaDefault(itemSchema));onChange([...arrayValue]);renderItems()};arrayHost.append(items,add);renderItems();return arrayHost}return capabilityPrimitiveControl(schema,value,onChange)}
function createCapabilitySchemaEditor(schema,key){const wrapper=document.createElement('div');let value=capabilityDraftValue(key,schema);const commit=next=>{value=next;capabilityTestDrafts.set(key,capabilityClone(next))};wrapper.className='capability-schema-editor';wrapper.append(capabilitySchemaNode(schema,value,commit));return{element:wrapper,read(){return capabilityClone(value)}}}
function clearCapabilityTestJson(){capabilityTestLogLines.length=0;if(capabilityTestLogRenderTimer!==null){clearTimeout(capabilityTestLogRenderTimer);capabilityTestLogRenderTimer=null}q('capabilityTestLog').textContent=tr('workspace.select_capability_test_help')}
function renderCapabilityTestJson(){capabilityTestLogRenderTimer=null;const log=q('capabilityTestLog');log.textContent=capabilityTestLogLines.join(nl+nl);log.scrollTop=log.scrollHeight}
function appendCapabilityTestJson(action,payload){const entry={timestamp:new Date().toISOString(),action,payload};capabilityTestLogLines.push(JSON.stringify(entry,null,2));if(capabilityTestLogLines.length>capabilityTestLogLimit)capabilityTestLogLines.splice(0,capabilityTestLogLines.length-capabilityTestLogLimit);if(capabilityTestLogRenderTimer===null)capabilityTestLogRenderTimer=setTimeout(renderCapabilityTestJson,100)}
function capabilityTestInstanceEndpoint(suffix=''){return'/dev/api/capability-tests/instances/'+encodeURIComponent(capabilityTestInstance.instanceId)+(suffix?'/'+suffix:'')}
function setCapabilityTestBusy(value){capabilityTestBusy=value;q('runAllCapabilityTests').disabled=value;for(const button of q('capabilityTestDetail').querySelectorAll('button'))button.disabled=value||button.dataset.disabled==='true'}
function renderCapabilityTests(items=capabilityTestItems){const host=q('capabilityTestList');host.replaceChildren(...items.map(item=>{const button=document.createElement('button'),name=document.createElement('strong'),code=document.createElement('code'),contract=document.createElement('small'),state=document.createElement('span'),result=capabilityTestResults.get(item.code);button.type='button';button.className='capability-test-item'+(item.code===capabilityTestSelectedCode?' active':'');name.textContent=localizedCapabilityField(item,'name');code.textContent=item.code;contract.textContent=capabilityContract(item);state.className=result?.status||(!item.platformAvailable?'unavailable':'');state.textContent=result?tr('workspace.capability_result',{status:capabilityStatusText(result.status),message:result.message}):capabilityPlatformStatusText(item.platformAvailable);button.append(name,code,contract,state);button.onclick=()=>selectCapabilityTest(item.code);return button}));renderCapabilityTestDetail()}
function renderCapabilityTestDetail(){const host=q('capabilityTestDetail'),item=capabilityTestDefinition();host.replaceChildren();capabilityTestOptionsEditor=null;capabilityTestMethodEditors=new Map();if(!item){const empty=document.createElement('p');empty.className='capability-test-empty';empty.textContent=tr('workspace.select_capability_definition');host.append(empty);return}const header=document.createElement('header'),title=document.createElement('h2'),code=document.createElement('code'),description=document.createElement('p'),meta=document.createElement('small');title.textContent=localizedCapabilityField(item,'name');code.textContent=item.code;description.textContent=localizedCapabilityField(item,'description');meta.textContent=capabilityContract(item)+' · '+tr(item.platformAvailable?'workspace.platform_available':'workspace.platform_unavailable');header.append(title,code,description,meta);host.append(header);const instanceSection=document.createElement('section'),instanceHead=document.createElement('div'),instanceTitle=document.createElement('h3'),instanceState=document.createElement('span'),instanceActions=document.createElement('div');instanceTitle.textContent=tr('workspace.test_instance');instanceState.textContent=capabilityTestInstance?tr('workspace.instance_active',{id:capabilityTestInstance.instanceId}):tr('workspace.instance_not_created');instanceHead.className='capability-test-section-head';instanceHead.append(instanceTitle,instanceState);capabilityTestOptionsEditor=createCapabilitySchemaEditor(item.optionsSchema||{type:'object'},item.code+':options');const create=document.createElement('button'),dispose=document.createElement('button'),selfCheck=document.createElement('button');create.textContent=tr('workspace.create_test_instance');create.dataset.disabled=String(!item.platformAvailable||Boolean(capabilityTestInstance));create.disabled=!item.platformAvailable||Boolean(capabilityTestInstance);create.onclick=()=>createCapabilityTestInstance();dispose.textContent=tr('workspace.dispose_test_instance');dispose.dataset.disabled=String(!capabilityTestInstance);dispose.disabled=!capabilityTestInstance;dispose.onclick=()=>disposeCapabilityTestInstance();selfCheck.textContent=tr('workspace.run_plugin_self_check');selfCheck.dataset.disabled=String(!item.testable);selfCheck.disabled=!item.testable;selfCheck.onclick=()=>runCapabilityTests([item.code]);instanceActions.className='capability-test-actions';instanceActions.append(create,dispose,selfCheck);instanceSection.className='capability-test-section';instanceSection.append(instanceHead,capabilityTestOptionsEditor.element,instanceActions);host.append(instanceSection);const methodsSection=document.createElement('section'),methodsTitle=document.createElement('h3');methodsSection.className='capability-test-section';methodsTitle.textContent=tr('workspace.capability_methods');methodsSection.append(methodsTitle);const methods=Array.isArray(item.methods)?item.methods:[];if(!methods.length){const empty=document.createElement('p');empty.className='capability-test-muted';empty.textContent=tr('workspace.no_capability_methods');methodsSection.append(empty)}for(const method of methods){const card=document.createElement('article'),head=document.createElement('div'),name=document.createElement('strong'),activation=document.createElement('small'),description=document.createElement('p'),invoke=document.createElement('button'),key=item.code+':method:'+method.name,editor=createCapabilitySchemaEditor(method.argumentsSchema||{type:'object'},key);name.textContent=method.name;activation.textContent=method.requiresUserActivation?tr('workspace.requires_user_activation'):'';head.append(name,activation);description.textContent=String(method.description||'');invoke.textContent=tr('workspace.invoke_method',{method:method.name});invoke.dataset.disabled=String(!capabilityTestInstance);invoke.disabled=!capabilityTestInstance;invoke.onclick=()=>invokeCapabilityTestMethod(method.name);capabilityTestMethodEditors.set(method.name,editor);card.className='capability-method-card';card.append(head,description,editor.element,invoke);methodsSection.append(card)}host.append(methodsSection);const events=Array.isArray(item.events)?item.events:[];if(events.length){const eventsSection=document.createElement('section'),eventsHead=document.createElement('div'),eventsTitle=document.createElement('h3'),eventsState=document.createElement('span'),eventList=document.createElement('div'),actions=document.createElement('div'),start=document.createElement('button'),stop=document.createElement('button');eventsTitle.textContent=tr('workspace.continuous_events');eventsState.textContent=tr(capabilityTestStreaming?'workspace.continuous_test_running':'workspace.continuous_test_stopped');eventsHead.className='capability-test-section-head';eventsHead.append(eventsTitle,eventsState);for(const event of events){const eventRow=document.createElement('div'),name=document.createElement('code'),description=document.createElement('span');name.textContent=event.name;description.textContent=String(event.description||'');eventRow.append(name,description);eventList.append(eventRow)}eventList.className='capability-event-list';start.textContent=tr('workspace.start_continuous_test');start.dataset.disabled=String(!item.platformAvailable||capabilityTestStreaming);start.disabled=!item.platformAvailable||capabilityTestStreaming;start.onclick=()=>startCapabilityContinuousTest();stop.textContent=tr('workspace.stop_continuous_test');stop.dataset.disabled=String(!capabilityTestInstance||!capabilityTestStreaming);stop.disabled=!capabilityTestInstance||!capabilityTestStreaming;stop.onclick=()=>stopCapabilityContinuousTest();actions.className='capability-test-actions';actions.append(start,stop);eventsSection.className='capability-test-section capability-event-section'+(capabilityTestStreaming?' running':'');eventsSection.append(eventsHead,eventList,actions);host.append(eventsSection)}setCapabilityTestBusy(capabilityTestBusy)}
async function selectCapabilityTest(code){if(code===capabilityTestSelectedCode)return;if(capabilityTestInstance)await disposeCapabilityTestInstance({quiet:true});capabilityTestSelectedCode=code;capabilityTestStreaming=false;clearCapabilityTestJson();renderCapabilityTests()}
async function createCapabilityTestInstance({quiet=false}={}){const item=capabilityTestDefinition();if(!item||capabilityTestInstance||capabilityTestBusy)return false;if(!quiet)clearCapabilityTestJson();let options;try{options=capabilityTestOptionsEditor.read()}catch(error){q('capabilityTestSummary').textContent=error.message;return false}setCapabilityTestBusy(true);try{const data=await api('/dev/api/capability-tests/instances',{method:'POST',body:JSON.stringify({code:item.code,options})}).then(response=>response.json());capabilityTestInstance=data;capabilityTestStreaming=false;appendCapabilityTestJson('instance.create',data);if(!quiet)q('capabilityTestSummary').textContent=tr('workspace.test_instance_created');return true}catch(error){appendCapabilityTestJson('instance.create.error',error.payload||{message:error.message,status:error.status});q('capabilityTestSummary').textContent=error.message;return false}finally{capabilityTestBusy=false;renderCapabilityTests()}}
async function invokeCapabilityTestMethod(method,{quiet=false}={}){if(!capabilityTestInstance||capabilityTestBusy)return null;if(!quiet)clearCapabilityTestJson();const editor=capabilityTestMethodEditors.get(method);let argumentsValue;try{argumentsValue=editor?editor.read():{}}catch(error){q('capabilityTestSummary').textContent=error.message;return null}setCapabilityTestBusy(true);try{const data=await api(capabilityTestInstanceEndpoint('invoke'),{method:'POST',body:JSON.stringify({method,arguments:argumentsValue})}).then(response=>response.json());appendCapabilityTestJson('method.invoke',data);if(method==='start')capabilityTestStreaming=true;if(method==='stop')capabilityTestStreaming=false;if(!quiet)q('capabilityTestSummary').textContent=tr('workspace.capability_method_invoked',{method});return data}catch(error){appendCapabilityTestJson('method.invoke.error',{instanceId:capabilityTestInstance?.instanceId,method,error:error.payload||{message:error.message,status:error.status}});q('capabilityTestSummary').textContent=error.message;return null}finally{capabilityTestBusy=false;renderCapabilityTests()}}
async function disposeCapabilityTestInstance({quiet=false}={}){const instance=capabilityTestInstance;if(!instance)return;capabilityTestInstance=null;capabilityTestStreaming=false;try{const data=await api('/dev/api/capability-tests/instances/'+encodeURIComponent(instance.instanceId),{method:'DELETE'}).then(response=>response.json());appendCapabilityTestJson('instance.dispose',data);if(!quiet)q('capabilityTestSummary').textContent=tr('workspace.test_instance_disposed')}catch(error){appendCapabilityTestJson('instance.dispose.error',{instanceId:instance.instanceId,error:error.payload||{message:error.message,status:error.status}});if(!quiet)q('capabilityTestSummary').textContent=error.message}finally{renderCapabilityTests()}}
async function startCapabilityContinuousTest(){const item=capabilityTestDefinition();if(!item||capabilityTestBusy)return;clearCapabilityTestJson();const startMethod=(item.methods||[]).find(method=>method.name==='start');if(capabilityTestInstance)await disposeCapabilityTestInstance({quiet:true});if(!(await createCapabilityTestInstance({quiet:true})))return;if(startMethod){await invokeCapabilityTestMethod('start',{quiet:true});if(!capabilityTestStreaming)return}else{capabilityTestStreaming=true;renderCapabilityTests()}q('capabilityTestSummary').textContent=tr('workspace.continuous_test_started')}
async function stopCapabilityContinuousTest(){const item=capabilityTestDefinition();if(!item||!capabilityTestInstance||capabilityTestBusy)return;const stopMethod=(item.methods||[]).find(method=>method.name==='stop');if(stopMethod)await invokeCapabilityTestMethod('stop',{quiet:true});else await disposeCapabilityTestInstance({quiet:true});capabilityTestStreaming=false;renderCapabilityTests();q('capabilityTestSummary').textContent=tr('workspace.continuous_test_stopped')}
function handleCapabilityTestEvent(event){if(!capabilityTestInstance||event.instanceId!==capabilityTestInstance.instanceId)return;appendCapabilityTestJson(event.type==='capability.test.error'?'event.error':'event',event);if(event.type==='capability.test.error')q('capabilityTestSummary').textContent=String(event.error||'')}
async function stopCapabilityTests(){q('runAllCapabilityTests').disabled=false;if(capabilityTestInstance)await disposeCapabilityTestInstance({quiet:true});capabilityTestStreaming=false}
async function openCapabilityTests(){await stopCapabilityTests();capabilityTestResults=new Map();capabilityTestDrafts=new Map();capabilityTestSelectedCode='';clearCapabilityTestJson();q('capabilityTestSummary').textContent=tr('workspace.reading_capability_registry');q('capabilityTestModal').style.display='grid';const data=await api('/dev/api/capability-tests').then(r=>r.json());capabilityTestItems=data.capabilities||[];capabilityTestSelectedCode=capabilityTestItems[0]?.code||'';renderCapabilityTests();q('capabilityTestSummary').textContent=tr('workspace.capability_count',{count:formatInteger(capabilityTestItems.length)})}
async function runCapabilityTests(codes){if(capabilityTestBusy)return;clearCapabilityTestJson();const selectedCodes=Array.isArray(codes)&&codes.length?codes:null;setCapabilityTestBusy(true);q('capabilityTestSummary').textContent=tr('workspace.running_self_checks');try{const data=await api('/dev/api/capability-tests',{method:'POST',body:JSON.stringify({codes:selectedCodes,timeoutMs:3000})}).then(r=>r.json());for(const result of data.results||[])capabilityTestResults.set(result.code,result);appendCapabilityTestJson('self-test',data);q('capabilityTestSummary').textContent=tr('workspace.capability_self_check_result',{passed:formatInteger(data.passed),total:formatInteger(data.total)})}catch(error){appendCapabilityTestJson('self-test.error',error.payload||{message:error.message,status:error.status});q('capabilityTestSummary').textContent=error.message}finally{capabilityTestBusy=false;renderCapabilityTests()}}
q('extractForm').onsubmit=event=>submitExtractTreeZip(event);
q('projectTagAdd').onclick=addProjectTag;
q('projectTagInput').onkeydown=event=>{if(event.key==='Enter'){event.preventDefault();addProjectTag()}};
tree.oncontextmenu=event=>{if(!event.target.closest('summary,.file'))openTreeMenu(event,'',tree)};treeMenu.onclick=event=>{const action=event.target.closest('[data-tree-action]')?.dataset.treeAction;if(!action)return;closeTreeMenu();if(action==='new-file')createTreeFile().catch(e=>message.textContent=e.message);if(action==='new-directory')createTreeDirectory().catch(e=>message.textContent=e.message);if(action==='upload')fileUpload.click();if(action==='copy')rememberTreeEntry('copy');if(action==='cut')rememberTreeEntry('move');if(action==='paste')pasteTreeEntry().catch(e=>message.textContent=e.message);if(action==='extract')extractTreeZip().catch(e=>message.textContent=e.message);if(action==='history')openLocalHistory(treeMenuKind==='root'?'':treeMenuItemPath).catch(e=>message.textContent=e.message);if(action==='delete')deleteTreeEntry().catch(e=>message.textContent=e.message)};fileUpload.onchange=async()=>{const files=Array.from(fileUpload.files||[]);fileUpload.value='';if(files.length)await uploadTreeFiles(files).catch(e=>message.textContent=e.message)};q('restoreBefore').onclick=()=>restoreHistory('before').catch(e=>message.textContent=e.message);q('restoreAfter').onclick=()=>restoreHistory('after').catch(e=>message.textContent=e.message);document.addEventListener('pointerdown',event=>{if(!treeMenu.contains(event.target))closeTreeMenu()});window.addEventListener('resize',closeTreeMenu);window.addEventListener('blur',closeTreeMenu);
let aiApprovalQueue=[],activeAiApprovalId='',aiApprovalCountdown=null;
function removeAiApproval(approvalId){aiApprovalQueue=aiApprovalQueue.filter(item=>item.approvalId!==approvalId);if(activeAiApprovalId===approvalId)activeAiApprovalId='';renderAiApproval()}
function renderAiApproval(){if(aiApprovalCountdown){clearInterval(aiApprovalCountdown);aiApprovalCountdown=null}const approval=aiApprovalQueue[0],modal=q('aiApprovalModal');if(!approval){activeAiApprovalId='';modal.style.display='none';return}activeAiApprovalId=approval.approvalId;modal.style.display='grid';q('aiApprovalMessage').textContent=tr('workspace.ai_approval_message',{summary:approval.summary});q('aiApprovalDetail').textContent=approval.method+' '+approval.path+nl+tr('workspace.ai_operation',{value:approval.operationId})+nl+tr('workspace.ai_channel',{value:approval.channel})+(approval.projectId?nl+tr('workspace.ai_project',{value:approval.projectId}):'');q('aiApprovalProject').disabled=!approval.projectId;const updateCountdown=()=>{const remaining=Math.max(0,Math.ceil((Number(approval.expiresAt)-Date.now())/1000));q('aiApprovalCountdown').textContent=tr('workspace.ai_approval_countdown',{seconds:formatInteger(remaining)});if(remaining===0){message.textContent=tr('workspace.ai_approval_timed_out');removeAiApproval(approval.approvalId)}};updateCountdown();if(activeAiApprovalId===approval.approvalId)aiApprovalCountdown=setInterval(updateCountdown,250)}
function enqueueAiApproval(approval){if(!approval?.approvalId||aiApprovalQueue.some(item=>item.approvalId===approval.approvalId))return;aiApprovalQueue.push(approval);aiApprovalQueue.sort((left,right)=>Number(left.createdAt)-Number(right.createdAt));renderAiApproval()}
async function decideAiApproval(decision){const approvalId=activeAiApprovalId;if(!approvalId)return;for(const button of q('aiApprovalActions').querySelectorAll('button'))button.disabled=true;try{await api('/dev/api/ai-approvals/'+encodeURIComponent(approvalId),{method:'POST',body:JSON.stringify({decision})});removeAiApproval(approvalId);message.textContent=tr(decision==='reject'?'workspace.ai_operation_rejected':'workspace.ai_operation_allowed')}catch(error){message.textContent=error.message;await loadPendingAiApprovals()}finally{for(const button of q('aiApprovalActions').querySelectorAll('button'))button.disabled=false;const current=aiApprovalQueue[0];q('aiApprovalProject').disabled=!current?.projectId}}
async function loadPendingAiApprovals(){try{const data=await api('/dev/api/ai-approvals').then(response=>response.json()),ids=new Set((data.approvals||[]).map(item=>item.approvalId));aiApprovalQueue=aiApprovalQueue.filter(item=>ids.has(item.approvalId));for(const approval of data.approvals||[])if(!aiApprovalQueue.some(item=>item.approvalId===approval.approvalId))aiApprovalQueue.push(approval);aiApprovalQueue.sort((left,right)=>Number(left.createdAt)-Number(right.createdAt));renderAiApproval()}catch(error){console.warn(error)}}
