for(const modal of document.querySelectorAll('.modal')){
  bindModalFocusLifecycle(modal);
  if(modal.id==='publishModal'){
    bindModalKeyboard(modal,closePublishModal);
    continue
  }
  if(modal.id==='aiApprovalModal'){
    bindModalKeyboard(modal,null,{escapeCloses:false});
    continue
  }
  bindModalKeyboard(modal,()=>modal.querySelector('[data-close="'+modal.id+'"]')?.click())
}
treeMenu.addEventListener('keydown',event=>{const items=menuItems(treeMenu),index=items.indexOf(document.activeElement);if(event.key==='Escape'){event.preventDefault();const target=treeMenuTarget;closeTreeMenu();target?.focus?.();return}if(!['ArrowDown','ArrowUp','Home','End'].includes(event.key)||!items.length)return;event.preventDefault();const next=event.key==='Home'?0:event.key==='End'?items.length-1:event.key==='ArrowDown'?(index+1+items.length)%items.length:(index-1+items.length)%items.length;items[next].focus()});
